1	// ponytail: Intl only; swap for Temporal.ZonedDateTime once Node and Safari ship it
2	
3	const formatters = new Map<string, Intl.DateTimeFormat>();
4	
5	// Slot building calls these hundreds of times per request, so formatters are built once per locale, zone and options.
6	function formatter(locale: string, timeZone: string, options: Intl.DateTimeFormatOptions): Intl.DateTimeFormat {
7	  const key = `${locale}|${timeZone}|${JSON.stringify(options)}`;
8	  let f = formatters.get(key);
9	  if (!f) {
10	    if (formatters.size > 500) formatters.clear(); // ponytail: clear-all past 500 entries; an LRU if real zones ever churn
11	    f = new Intl.DateTimeFormat(locale, { ...options, timeZone });
12	    formatters.set(key, f);
13	  }
14	  return f;
15	}
16	
17	// ICU accepts "IST" and maps it to India, so a zone without a "/" is only valid as "UTC" (spec §7 rule 8).
18	export function isValidTimeZone(tz: string): boolean {
19	  if (tz !== 'UTC' && !tz.includes('/')) return false;
20	  try {
21	    formatter('en-US', tz, {});
22	    return true;
23	  } catch {
24	    return false;
25	  }
26	}
27	
28	/** UTC offset of `tz` at the instant `at`, in minutes (-240, 330). */
29	export function offsetMinutes(at: Date, tz: string): number {
30	  const name = formatter('en-US', tz, { timeZoneName: 'longOffset' })
31	    .formatToParts(at)
32	    .find((p) => p.type === 'timeZoneName')?.value;
33	  if (name === 'GMT') return 0;
34	  const m = name?.match(/^GMT([+\-−])(\d\d):(\d\d)$/);
35	  if (!m) throw new Error(`cannot read the UTC offset of ${tz}: ${name}`);
36	  return (m[1] === '+' ? 1 : -1) * (Number(m[2]) * 60 + Number(m[3]));
37	}
38	
39	/** The calendar date at `at` in `tz`, as 'YYYY-MM-DD'. */
40	export function localDate(at: Date, tz: string): string {
41	  const parts = formatter('en-US', tz, { year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(at);
42	  const part = (type: string) => parts.find((p) => p.type === type)?.value;
43	  return `${part('year')}-${part('month')}-${part('day')}`;
44	}
45	
46	function parseDate(date: string): [number, number, number] {
47	  const [y, m, d] = date.split('-').map(Number);
48	  return [y!, m!, d!];
49	}
50	
51	/** Day of the week of a calendar date, 0 = Sunday. */
52	export function weekdayOf(date: string): number {
53	  const [y, m, d] = parseDate(date);
54	  return new Date(Date.UTC(y, m - 1, d)).getUTCDay();
55	}
56	
57	export function addDays(date: string, days: number): string {
58	  const [y, m, d] = parseDate(date);
59	  return new Date(Date.UTC(y, m - 1, d + days)).toISOString().slice(0, 10);
60	}
61	
62	/**
63	 * The instant at which `tz` reads `date` `time` ('HH:MM' or 'HH:MM:SS').
64	 * Matches Temporal's 'compatible' rule: a repeated hour resolves to its first pass,
65	 * and a time skipped by a clock change moves forward by the gap.
66	 */
67	export function zonedTimeToInstant(date: string, time: string, tz: string): Date {
68	  const [y, m, d] = parseDate(date);
69	  const [hh, mm, ss = 0] = time.split(':').map(Number);
70	  const wall = Date.UTC(y, m - 1, d, hh!, mm!, ss); // the wall-clock reading as if it were UTC
71	  const early = offsetMinutes(new Date(wall - 86_400_000), tz);
72	  const late = offsetMinutes(new Date(wall + 86_400_000), tz);
73	  const valid = [early, late]
74	    .map((o) => wall - o * 60_000)
75	    .filter((t) => offsetMinutes(new Date(t), tz) * 60_000 === wall - t);
76	  // repeated hour: two valid instants, take the earlier; gap: none valid, move forward by the gap
77	  return new Date(valid.length ? Math.min(...valid) : wall - early * 60_000);
78	}
